draw:
var g = 9.8, h = p.h, e = p.e;
var floorY = H - 26, topY = 30;
var sc = (floorY - topY) / h;
var tf = Math.sqrt(2 * h / g);
var total = tf + 2 * tf * e / (1 - e) + 0.6;
var tt = t % total;
var y = 0, n = 0, peak = h;
if (tt < tf) { y = h - 0.5 * g * tt * tt; n = 0; peak = h; }
else {
  var rem = tt - tf, vn = g * tf * e;
  n = 1; peak = vn * vn / (2 * g); y = 0;
  for (var i = 0; i < 80; i++) {
    var dur = 2 * vn / g;
    if (rem < dur) { y = vn * rem - 0.5 * g * rem * rem; peak = vn * vn / (2 * g); n = i + 1; break; }
    rem -= dur; vn *= e; n = i + 2; peak = vn * vn / (2 * g); y = 0;
  }
}
if (y < 0) y = 0;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(0, floorY); ctx.lineTo(W, floorY); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("floor", 6, floorY + 15);

var bx = W * 0.34;

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(W * 0.10, floorY - h * sc); ctx.lineTo(W * 0.78, floorY - h * sc); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("drop height h = " + h.toFixed(2) + " m", W * 0.80, floorY - h * sc + 4);

var k;
for (k = 1; k <= 5; k++) {
  var hk = h * Math.pow(e, 2 * k);
  if (hk * sc < 4) break;
  ctx.strokeStyle = C.rule;
  ctx.setLineDash([2, 4]);
  ctx.beginPath(); ctx.moveTo(W * 0.62, floorY - hk * sc); ctx.lineTo(W * 0.78, floorY - hk * sc); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.faint;
  ctx.fillText("bounce " + k + ": " + hk.toFixed(2) + " m", W * 0.80, floorY - hk * sc + 4);
}

ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(W * 0.16, floorY - peak * sc); ctx.lineTo(W * 0.56, floorY - peak * sc); ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(W * 0.14, floorY); ctx.lineTo(W * 0.14, floorY - peak * sc); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText("current peak", W * 0.12, floorY - peak * sc / 2);

ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(bx, floorY - y * sc - 9, 9, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("e = " + e.toFixed(2) + "  so each bounce keeps e squared = " + (e * e).toFixed(3) + " of the height", 6, 16);

var totalDist = h * (1 + e * e) / (1 - e * e);
out.note = "bounce " + n + ", peak " + peak.toFixed(3) + " m, total path over all bounces " + totalDist.toFixed(2) + " m";
